let arr = new Array(2); // 创建长度为 2 的数组
console.log(arr); // [ <2 empty items> ]

arr = new Array("2");
console.log(arr); // [ '2' ]

arr = new Array(1, 2, 3);
console.log(arr); // [ 1, 2, 3 ]

let arr = Array.of(2);
console.log(arr); // [ 2 ]

arr = Array.of(1, 2, 3);
console.log(arr); // [ 1, 2, 3 ]
